#include <string>
#include <cctype>  // For tolower

using namespace std;

bool isAnagram(string str1, string str2) {
    if (str1.length() != str2.length()) {
        return false;
    }

    // Convert to lowercase
    transform(str1.begin(), str1.end(), str1.begin(), ::tolower);
    transform(str2.begin(), str2.end(), str2.begin(), ::tolower);

    sort(str1.begin(), str1.end());
    sort(str2.begin(), str2.end());

    return str1 == str2;
}
```

---

### Explanation:
- **`transform`**: Converts all characters to lowercase to ensure case-insensitive comparison.
- **`tolower`**: From `<cctype>`, ensures uppercase letters are normalized.
- **`sort`**: Sorts the strings to compare character sequences.

